CREATE OR REPLACE FUNCTION finance_private.customer_credit_application_context(_tenant uuid, _credit uuid, _receivable uuid, _amount text, _application uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare credit jsonb;target jsonb;r public.receivables%rowtype;app finance_private.customer_credit_application_events%rowtype;amount bigint;remaining numeric;blockers jsonb:='[]';result jsonb;
begin
 perform finance_private.require_access(_tenant);
 if _amount is null or _amount!~'^[1-9][0-9]{0,13}$' then raise exception 'finance_credit_amount_invalid' using errcode='22023';end if;amount:=_amount::bigint;
 credit:=finance_private.customer_credit_position(_tenant,_credit);select * into r from public.receivables where tenant_id=_tenant and id=_receivable;
 if not found then raise exception 'finance_credit_target_missing' using errcode='22023';end if;
 target:=public._receivable_financial_snapshot(_tenant,_receivable);
 if credit->'valid' is distinct from 'true'::jsonb then blockers:=blockers||jsonb_build_array('credit_source_unverified');end if;
 if r.client_id::text is distinct from credit->>'payer_id' then blockers:=blockers||jsonb_build_array('credit_payer_mismatch');end if;
 if target->'requires_reconciliation' is distinct from 'false'::jsonb then blockers:=blockers||jsonb_build_array('credit_target_unverified');end if;
 if _application is null then
  if target->'can_receive' is distinct from 'true'::jsonb then blockers:=blockers||jsonb_build_array('credit_target_not_collectible');end if;
  if amount>coalesce((credit->>'available_cents')::numeric,-1) then blockers:=blockers||jsonb_build_array('credit_capacity_exceeded');end if;
  if amount>coalesce((target->>'open_cents')::numeric,-1) then blockers:=blockers||jsonb_build_array('credit_target_capacity_exceeded');end if;
 else
  select * into app from finance_private.customer_credit_application_events where tenant_id=_tenant and id=_application and credit_id=_credit and receivable_id=_receivable and action='apply';
  if not found then raise exception 'finance_credit_application_missing' using errcode='22023';end if;
  select app.amount_cents-coalesce(sum(amount_cents),0) into remaining from finance_private.customer_credit_application_events where tenant_id=_tenant and application_id=app.id and action='release';
  if amount>remaining then blockers:=blockers||jsonb_build_array('credit_release_capacity_exceeded');end if;
  if r.status='cancelled' then blockers:=blockers||jsonb_build_array('credit_target_cancelled');end if;
 end if;
 result:=jsonb_build_object('version',1,'tenant_id',_tenant,'actor_id',auth.uid(),'action',case when _application is null then 'apply' else 'release' end,'application_id',_application,'credit_id',_credit,'receivable_id',_receivable,'amount_cents',_amount,'credit',credit-'history'-'refund_history','target',jsonb_build_object('receivable_id',r.id,'payer_id',r.client_id,'reference',target->'reference','status',r.status,'nominal_cents',target->>'amount_cents','cash_received_cents',target->>'cash_received_cents','credit_applied_cents',target->>'credit_applied_cents','settled_cents',target->>'settled_cents','open_cents',target->>'open_cents','revision',target->'revision'),'release_available_cents',remaining::text,'eligible',blockers='[]'::jsonb,'can_execute',false,'blockers',blockers);
 return result||jsonb_build_object('revision',md5(result::text));
end$function$

CREATE OR REPLACE FUNCTION finance_private.release_receivable_customer_credits(_tenant uuid, _receivable uuid, _reason text, _observation uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a record;position jsonb;event_id uuid;req uuid;result jsonb;actor uuid;actor_name text;
begin
 perform pg_advisory_xact_lock(hashtextextended('fiscal:'||_tenant::text,0));perform pg_advisory_xact_lock(hashtextextended(_tenant::text||':finance',0));
 if _observation is null then perform finance_private.require_access(_tenant);actor:=auth.uid();actor_name:=actor::text;
 else
  if not exists(select 1 from public.finance_fiscal_observations o join public.finance_fiscal_receivable_origins origin on origin.tenant_id=o.tenant_id and origin.emission_id=o.emission_id join public.hub_fiscal_emissions e on e.tenant_id=o.tenant_id and e.id=o.emission_id where o.id=_observation and o.tenant_id=_tenant and origin.receivable_id=_receivable and o.snapshot->>'status'='cancelled' and o.snapshot->>'environment'='production' and e.status='cancelled' and e.environment='production' and e.dispatch_state='recorded') then raise exception 'finance_credit_cancellation_unproven' using errcode='23514';end if;
  actor_name:='Processamento fiscal';
 end if;
 for a in select app.*,app.amount_cents-(select coalesce(sum(release.amount_cents),0) from finance_private.customer_credit_application_events release where release.tenant_id=app.tenant_id and release.application_id=app.id and release.action='release') remaining from finance_private.customer_credit_application_events app where app.tenant_id=_tenant and app.receivable_id=_receivable and app.action='apply' order by app.id loop
  if a.remaining=0 then continue;end if;
  position:=finance_private.customer_credit_position(_tenant,a.credit_id);if position->'valid' is distinct from 'true'::jsonb or a.remaining<0 then raise exception 'finance_credit_cancellation_evidence_invalid' using errcode='23514';end if;
  event_id:=gen_random_uuid();req:=gen_random_uuid();result:=jsonb_build_object('version',1,'tenant_id',_tenant,'actor_id',actor,'request_id',req,'event_id',event_id,'application_id',a.id,'action','release','credit_id',a.credit_id,'receivable_id',_receivable,'amount_cents',a.remaining::text,'cash_movement_created',false,'observation_id',_observation);
  if actor is not null then insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,before_data,after_data) values(_tenant,'customer_credit_application',event_id,'customer_credit_application_released',actor,actor_name,_reason,position-'history',result);end if;
  insert into finance_private.customer_credit_application_events(id,tenant_id,credit_id,receivable_id,action,application_id,amount_cents,request_id,actor_id,actor_name,reason,source_revision,source_snapshot,payload_hash,result,observation_id) values(event_id,_tenant,a.credit_id,_receivable,'release',a.id,a.remaining,req,actor,actor_name,_reason,position->>'source_revision',position-'history',md5(result::text),result,_observation);
 end loop;
end$function$

CREATE OR REPLACE FUNCTION public._guard_receivable_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_total numeric;v_has boolean;begin
 if tg_op='INSERT' then
  if coalesce(new.received_amount,0)<>0 or new.status in('received','partial') then raise exception 'financial_versioned_command_required' using errcode='55000';end if;
  return new;
 end if;
 select exists(select 1 from public.receivables_payments where tenant_id=old.tenant_id and receivable_id=old.id) into v_has; v_has:=v_has or exists(select 1 from finance_private.customer_credit_application_events where tenant_id=old.tenant_id and receivable_id=old.id);
 if tg_op='DELETE' then
  if v_has or old.client_invoice_id is not null or exists(select 1 from public.closing_reports where tenant_id=old.tenant_id and receivable_id=old.id) then
   raise exception 'financial_receivable_history_is_immutable' using errcode='55000';end if;return old;
 end if;
 if (new.id,new.tenant_id) is distinct from (old.id,old.tenant_id) or ((v_has or old.client_invoice_id is not null) and
  (new.amount,new.client_id,new.client_invoice_id,new.closing_report_id) is distinct from (old.amount,old.client_id,old.client_invoice_id,old.closing_report_id)) then
  raise exception 'financial_receivable_identity_is_immutable' using errcode='55000';end if;
 select coalesce(sum(p.amount),0) into v_total from public.receivables_payments p where p.tenant_id=old.tenant_id and p.receivable_id=old.id
  and not exists(select 1 from public.receivable_payment_reversals rv where rv.tenant_id=p.tenant_id and rv.payment_id=p.id) and not exists(select 1 from public.finance_receipt_allocation_corrections correction where correction.tenant_id=p.tenant_id and correction.payment_id=p.id) and not exists(select 1 from public.finance_customer_credits credit where credit.tenant_id=p.tenant_id and credit.payment_id=p.id);
 select net into v_total from public._receivable_ledger_evidence(old.tenant_id,old.id); if coalesce(new.received_amount,0)<>v_total or v_total<0 or v_total>new.amount
  or (new.status='received' and (v_total<=0 or v_total<>new.amount)) or (new.status='partial' and (v_total<=0 or v_total>=new.amount))
  or (new.status in('pending','invoiced','cancelled') and v_total<>0) then
  raise exception 'financial_ledger_requires_reconciliation' using errcode='55000';end if;
 return new;
end;$function$

CREATE OR REPLACE FUNCTION public._invoice_lifecycle_snapshot(_tenant uuid, _id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare inv public.client_invoices%rowtype;r public.receivables%rowtype;c public.closing_reports%rowtype;ledger record;
 v_valid boolean;v_consistent boolean;v_report_count int;v_result jsonb;v_history jsonb;v_charges jsonb;v_details jsonb;
begin
 select * into inv from public.client_invoices where tenant_id=_tenant and id=_id;if not found then raise exception 'invoice_not_found' using errcode='23514';end if;
 select * into r from public.receivables where tenant_id=_tenant and id=inv.receivable_id;
 select count(*) into v_report_count from public.closing_reports where tenant_id=_tenant and (client_invoice_id=inv.id or receivable_id=r.id);
 select * into c from public.closing_reports where tenant_id=_tenant and (client_invoice_id=inv.id or receivable_id=r.id) order by id limit 1;
 select * into ledger from public._receivable_ledger_evidence(_tenant,r.id);
 v_valid:=r.id is not null and r.client_invoice_id=inv.id and r.client_id=inv.client_id and r.amount=inv.total_amount and inv.total_amount>0 and v_report_count<=1
  and ledger.valid and ledger.net between 0 and r.amount and coalesce(r.received_amount,0)=ledger.net
  and not exists(select 1 from public.receivables other where other.tenant_id=_tenant and other.client_invoice_id=inv.id and other.id<>r.id)
  and (c.id is null or (c.receivable_id=r.id and c.client_invoice_id=inv.id and c.total_amount=r.amount and c.received_amount=ledger.net));
 v_consistent:=v_valid and not (public._receivable_financial_snapshot(_tenant,r.id)->>'requires_reconciliation')::boolean
  and not exists(select 1 from public.client_invoice_charges ch where ch.tenant_id=_tenant and ch.invoice_id=inv.id and (ch.cancelled_at is null)<>(inv.status<>'cancelled'))
  and (c.id is null or inv.status<>'cancelled' or not exists(select 1 from public.closing_report_charge_claims where tenant_id=_tenant and report_id=c.id and released_at is null));
 select coalesce(jsonb_agg(to_jsonb(ch) order by ch.sort_order,ch.id),'[]') into v_charges from public.client_invoice_charges ch where tenant_id=_tenant and invoice_id=inv.id;
 select coalesce(jsonb_agg(to_jsonb(d) order by d.sort_order,d.id),'[]') into v_details from public.client_invoice_details d where tenant_id=_tenant and invoice_id=inv.id;
 select coalesce(jsonb_agg(x.value order by x.created_at desc,x.id),'[]') into v_history from(
  select id,created_at,jsonb_build_object('id',id,'action',action,'reason',reason,'created_at',created_at) value from public.client_invoice_commands where tenant_id=_tenant and invoice_id=inv.id order by created_at desc,id limit 20) x;
 v_result:=jsonb_build_object('version',1,'tenant_id',_tenant,'actor_id',auth.uid(),'invoice_id',inv.id,'report_id',c.id,'receivable_id',r.id,
  'invoice_number',inv.invoice_number,'status',inv.status,'amount_cents',(inv.total_amount*100)::bigint,'received_cents',(ledger.net*100)::bigint,
  'open_cents',(case when inv.status='cancelled' then 0 else greatest(0,inv.total_amount-ledger.net) end*100)::bigint,
  'requires_reconciliation',not coalesce(v_consistent,false),'can_mark_sent',coalesce(v_consistent,false) and inv.status in('generated','sent','paid'),
  'can_cancel',coalesce(v_valid,false) and (select net from finance_private.cash_receivable_ledger_evidence(_tenant,r.id))=0 and inv.status in('generated','sent','paid','cancelled') and public.is_tenant_admin(_tenant),
  'can_reactivate',coalesce(v_valid,false) and inv.status='cancelled' and public.is_tenant_admin(_tenant),'history',v_history,
  'evidence',jsonb_build_object('invoice',to_jsonb(inv),'receivable',to_jsonb(r),'closing',case when c.id is null then null else to_jsonb(c) end,'charges',v_charges,'details',v_details));
 return v_result||jsonb_build_object('revision',md5(v_result::text));
end;$function$

CREATE OR REPLACE FUNCTION public._lock_receivable_financial_graph(_tenant uuid, _id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_invoice uuid;begin
 perform pg_advisory_xact_lock(hashtextextended('fiscal:'||_tenant::text,0));
 select client_invoice_id into v_invoice from public.receivables where tenant_id=_tenant and id=_id;
 perform id from public.closing_reports where tenant_id=_tenant and (receivable_id=_id or client_invoice_id=v_invoice) order by id for update nowait;
 perform id from public.client_invoices where tenant_id=_tenant and (id=v_invoice or receivable_id=_id) order by id for update nowait;
 perform id from public.receivables where tenant_id=_tenant and id=_id for update nowait;
 if not found then raise exception 'financial_receivable_not_found' using errcode='23514';end if;
end;$function$

CREATE OR REPLACE FUNCTION public._receivable_financial_snapshot(_tenant uuid, _id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare r public.receivables%rowtype;inv public.client_invoices%rowtype;c public.closing_reports%rowtype;
 credit_evidence jsonb;cash_net numeric;v_net numeric;v_count bigint;v_valid boolean;v_structural boolean:=true;v_balanced boolean;v_reason text;v_history jsonb;v_banks jsonb;v_result jsonb;v_invoice_count int;v_closing_count int;
begin
 select * into r from public.receivables where tenant_id=_tenant and id=_id;
 if not found then raise exception 'financial_receivable_not_found' using errcode='23514';end if;
 select count(*) into v_invoice_count from public.client_invoices where tenant_id=_tenant and (id=r.client_invoice_id or receivable_id=r.id);
 select * into inv from public.client_invoices where tenant_id=_tenant and (id=r.client_invoice_id or receivable_id=r.id) order by id limit 1;
 select count(*) into v_closing_count from public.closing_reports where tenant_id=_tenant and (receivable_id=r.id or (inv.id is not null and client_invoice_id=inv.id));
 select * into c from public.closing_reports where tenant_id=_tenant and (receivable_id=r.id or (inv.id is not null and client_invoice_id=inv.id)) order by id limit 1;
 if v_invoice_count>1 or v_closing_count>1 or r.amount<=0 or r.amount<>round(r.amount,2) or r.amount>999999999999.99
  or (r.client_invoice_id is not null and (inv.id is distinct from r.client_invoice_id or inv.receivable_id is distinct from r.id))
  or (inv.id is not null and (r.client_invoice_id is distinct from inv.id or inv.total_amount is distinct from r.amount or inv.client_id is distinct from r.client_id))
  or (c.id is not null and (c.receivable_id is distinct from r.id or c.client_invoice_id is distinct from inv.id or c.total_amount is distinct from r.amount))
  or (r.closing_report_id is not null and r.closing_report_id is distinct from c.id) then
  v_structural:=false;v_reason:='financial_graph_requires_reconciliation';end if;
 select net,payment_count,valid into v_net,v_count,v_valid from public._receivable_ledger_evidence(_tenant,_id);
 if not v_valid or v_net<0 or v_net>r.amount then v_structural:=false;v_reason:='financial_ledger_evidence_requires_reconciliation';end if;
 v_balanced:=coalesce(r.received_amount,0)=v_net
  and r.status is not distinct from (case when r.status='cancelled' and v_net=0 then 'cancelled' when v_net>=r.amount then 'received'
   when v_net>0 then 'partial' when inv.id is not null then 'invoiced' else 'pending' end)
  and (inv.id is null or inv.status is not distinct from (case when inv.status='cancelled' and v_net=0 then 'cancelled'
   when v_net>=r.amount then 'paid' when inv.sent_at is not null then 'sent' else 'generated' end))
  and (c.id is null or (c.received_amount=v_net and c.open_amount=(case when r.status='cancelled' then 0 else greatest(0,r.amount-v_net) end)
   and c.status is not distinct from (case when c.status='cancelled' and r.status='cancelled' and inv.status='cancelled' and v_net=0 then 'cancelled' when c.status='overdue' and c.expected_payment_date<current_date and v_net<r.amount then 'overdue'
    when v_net>=r.amount then 'paid' when v_net>0 then 'partially_paid' else 'invoiced' end)
   and c.payment_status is not distinct from (case when c.status='overdue' then 'overdue' when v_net>=r.amount then 'paid'
    when v_net>0 then 'partially_paid' else 'unpaid' end)));
 if not v_balanced and v_reason is null then v_reason:='financial_projection_requires_reconciliation';end if;
 if (inv.status='cancelled' or r.status='cancelled') and (v_net>0 or r.status<>'cancelled' or (inv.id is not null and inv.status<>'cancelled') or (c.id is not null and c.status<>'cancelled')) then
  v_structural:=false;v_reason:='financial_cancelled_graph_requires_reconciliation';end if;
 select coalesce(jsonb_agg(x.value order by x.received_at desc,x.id),'[]') into v_history from (
  select p.id,p.received_at,jsonb_build_object('id',p.id,'amount_cents',(p.amount*100)::bigint,'received_at',p.received_at,'method',p.method,
   'notes',p.notes,'bank_account_id',p.bank_account_id,'bank_account_name',a.name,'attachment_path',p.attachment_url,
   'reversed_at',rv.created_at,'reversal_reason',rv.reason,'allocation_correction',(select jsonb_build_object('id',correction.id,'actor_name',correction.actor_name,'actor_id',correction.actor_id,'reason',correction.reason,'created_at',correction.created_at) from public.finance_receipt_allocation_corrections correction where correction.tenant_id=p.tenant_id and correction.payment_id=p.id),'credit_id',(select credit.id from public.finance_customer_credits credit where credit.tenant_id=p.tenant_id and credit.payment_id=p.id)) value
  from public.receivables_payments p left join public.bank_accounts a on a.tenant_id=p.tenant_id and a.id=p.bank_account_id
  left join public.receivable_payment_reversals rv on rv.tenant_id=p.tenant_id and rv.payment_id=p.id
  where p.tenant_id=_tenant and p.receivable_id=_id order by p.received_at desc,p.id limit 500
 ) x;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name) order by a.name,a.id),'[]') into v_banks from public.bank_accounts a where a.tenant_id=_tenant and a.active;
 v_result:=jsonb_build_object('version',1,'tenant_id',_tenant,'actor_id',auth.uid(),'receivable_id',r.id,'invoice_id',inv.id,'report_id',c.id,
  'reference',coalesce(r.invoice_number,r.description,r.id::text),'status',r.status,'amount_cents',(r.amount*100)::bigint,
  'received_cents',(v_net*100)::bigint,'open_cents',((case when r.status='cancelled' then 0 else greatest(0,r.amount-v_net) end)*100)::bigint,
  'requires_reconciliation',not(v_structural and v_balanced),'reconciliation_reason',v_reason,
  'can_receive',v_structural and v_balanced and r.status<>'cancelled' and coalesce(inv.status,'generated')<>'cancelled' and v_net<r.amount,
  'can_reverse',v_structural and v_balanced and v_net>0 and coalesce(public.is_tenant_admin(_tenant),false),
  'can_reconcile',v_structural and not v_balanced and v_count>0 and coalesce(public.is_tenant_admin(_tenant),false),
  'payments',v_history,'history_complete',v_count<=500,'payment_count',v_count,'bank_accounts',v_banks,
  'evidence',jsonb_build_object('receivable',to_jsonb(r),'invoice',case when inv.id is null then null else to_jsonb(inv) end,'closing',case when c.id is null then null else to_jsonb(c) end));

 v_result:=v_result||jsonb_build_object('fiscal_block_reason',finance_private.receivable_fiscal_issue(_tenant,_id));
 if v_result->>'fiscal_block_reason' is not null then v_result:=v_result||jsonb_build_object('can_receive',false);end if;

 v_result:=v_result||finance_private.unloading_receivable_source_context(_tenant,_id);
 if v_result->>'source_issue' is not null then v_result:=v_result||jsonb_build_object('can_receive',false); end if;
 credit_evidence:=finance_private.receivable_credit_evidence(_tenant,_id); select net into cash_net from finance_private.cash_receivable_ledger_evidence(_tenant,_id); v_result:=v_result||jsonb_build_object('cash_received_cents',case when v_structural then (cash_net*100)::bigint end,'credit_applied_cents',case when v_structural then (credit_evidence->>'applied_cents')::bigint end,'settled_cents',case when v_structural then (v_net*100)::bigint end,'can_reverse',coalesce((v_result->>'can_reverse')::boolean,false) and cash_net>0,'credit_revision',credit_evidence->'revision','credit_application_count',jsonb_array_length(credit_evidence->'history')); return v_result||jsonb_build_object('revision',md5(v_result::text));
end;$function$
